// metadataCapabilityID is the capability id every metadata_source plugin
// advertises — the cmd manifest and the module seed agree ("default") — so the
// interactive search and identify actions resolve the typed client through it.
const metadataCapabilityID = "default"

// identifyOwner is the lease owner tag the identify action claims rows under —
// distinct from the workers' and the sweep's owners so a leaked lease is
// attributable in debugging.
const identifyOwner = "identify"

// errEmptyExternalID guards the identify anchor against an empty pick (the api
// validates too; the queue refuses before touching the row).
var errEmptyExternalID = errors.New("enrich: identify: empty external_id")

// relaySearchBudget is the search poll's give-up budget (ruled OQ-6, D8): a
// held search request waits at most this long for its relay job to reach a
// terminal answer before it replies with the upstream error. A named constant,
// deliberately NOT an env knob — a UX budget, not a tuning surface (design.md
// D8).
const relaySearchBudget = 60 * time.Second

// relaySearchPollInterval is the poll granularity: one relay_jobs read per
// tick (a newest-row lookup over the S10 seam — relay.go's Consult precedent)
// separated by a cancellable sleep. Short, so a job a client completes lands
// in the answer within a tick of its ingest; tests drive the budget with the
// package clock, never by out-waiting this interval.
const relaySearchPollInterval = 250 * time.Millisecond

// resolveServerSecrets resolves the plugin's binding secrets through the ONE
// serverAuth iteration over its module bindings (chain.go): the FIRST
// resolving binding wins — (values, true); anything else answers (nil, false).
// The vacuous cases keep the pre-SERVER shape: a nil Deps.RequiredSecrets or
// a plugin declaring no names answers (nil, true). Its two consumers share
// the answer so they can never disagree about "configured" (sourceConfigured
// keeps the boolean; SearchSource retains the values for the fetch AND the
// relay plan — a relayed search job never carries a {server:...}
// placeholder).
func (q *Queue) resolveServerSecrets(pluginID string) (map[string]string, bool) {
	if q.deps.RequiredSecrets == nil {
		return nil, true
	}
	if len(q.deps.RequiredSecrets(pluginID)) == 0 {
		return nil, true
	}
	if q.deps.Modules == nil {
		return nil, false
	}
	mods, err := q.deps.Modules.List()
	if err != nil {
		return nil, false
	}
	for _, mod := range mods {
		for _, src := range mod.MetadataSources {
			if src.PluginID != pluginID {
				continue
			}
			if secrets, ok := serverAuth(src, q.deps.RequiredSecrets); ok {
				return secrets, true
			}
		}
	}
	return nil, false
}

// sourceConfigured runs the interactive producers' pre-action required-secrets
// check (tmdb-enrichment D3): configured iff resolveServerSecrets resolves a
// declared name against one binding; otherwise the producers answer
// ErrUnconfiguredSource.
func (q *Queue) sourceConfigured(pluginID string) bool {
	_, ok := q.resolveServerSecrets(pluginID)
	return ok
}

// relayStateClaimed names the state a live claim stamps (the store's one
// conditional UPDATE writes it; relay.go names only the states IT moves —
// done|failed). The search poll reads it to observe an abandoned lease.
const relayStateClaimed = "claimed"

// SearchSource serves the identify overlay's interactive search
// (identify-match-override): resolve the typed client, SearchSpecs, execute
// the spec through the queue's own FetchGate with the plugin's resolved
// binding secrets (resolveServerSecrets), SearchResults — candidates returned
// as convention-field maps. A source without search surfaces
// sdk.ErrSearchUnsupported (searchSentinel re-wraps across the gRPC seam).
// An UNCONFIGURED source (tmdb-enrichment D3) answers ErrUnconfiguredSource
// before SearchSpecs executes — never a doomed anonymous fetch. A
// NETWORK-class fetch failure with the relay live rides the client relay
// instead (ruled OQ-6/D8): searchOverRelay holds and polls inside this
// closure, so the api endpoint and this signature stay byte-identical; every
// other failure keeps the immediate answer.
func (q *Queue) SearchSource(ctx context.Context, pluginID, query, kind string) ([]map[string]any, error) {
	if q.resolve == nil {
		return nil, errors.New("enrich: search: no plugin resolver")
	}
	md, err := q.resolve(pluginID, metadataCapabilityID)
	if err != nil {
		return nil, err
	}
	if !q.sourceConfigured(pluginID) { // D3: dormant — never a doomed fetch
		return nil, sourcestate.ErrUnconfiguredSource
	}
	// The executor resolves the plugin's binding secrets exactly like the
	// derivation chain (resolveServerSecrets — the serverAuth iteration) and
	// passes them to BOTH consumers below: fetchSource substitutes server
	// refs core-side, and the relay plan is built server-authored. A source
	// the pre-check called configured whose spec still fails on a redacted_ref
	// (a client:-scoped ref — Mode B — or a name outside the resolved binding)
	// is NOT an upstream failure: the fetch never left the spec, so the D3/3.4
	// law answers ErrUnconfiguredSource, never a raw 502 upstream_error.
	secrets, configured := q.resolveServerSecrets(pluginID)
	if !configured { // D3: dormant — never a doomed fetch
		return nil, sourcestate.ErrUnconfiguredSource
	}
	specs, err := md.SearchSpecs(ctx, &metadatav1.SearchSpecsRequest{Query: query, Kind: kind})
	if err != nil {
		return nil, searchSentinel(err)
	}
	body, status, headers, err := fetchSource(ctx, q.deps.FetchGate, pluginID, specs.GetSpec(), secrets)
	if err != nil {
		if errors.Is(err, errRedactedRef) { // 3.4's 503 law — the upstream did not fail
			return nil, fmt.Errorf("enrich: search fetch: %w", sourcestate.ErrUnconfiguredSource)
		}
		// Ruled OQ-6 (D8): a NETWORK-class fetch rides the relay — the job
		// enqueues for the plugin and this closure holds and polls it. Every
		// other condition keeps today's immediate answer bit-for-bit: relay
		// disabled (nil Deps.Relay, the chain's same rule), a non-network
		// class, a dying context (no durable relay state off a dead request),
		// or a plan that will not build.
		if q.deps.Relay != nil && ctx.Err() == nil && classifyFetchError(err) == fetchClassNetwork {
			if plan := buildPlan(specs.GetSpec(), nil, secrets); plan != nil {
				return q.searchOverRelay(ctx, md, pluginID, query, kind, plan, err)
			}
		}
		return nil, fmt.Errorf("enrich: search fetch: %w", err)
	}
	return searchResults(ctx, md, query, kind, body, status, headers)
}

// searchResults runs the plugin's result conversion over one fetched response
// and flattens the candidates to the convention-field maps — the identical
// shape the direct server fetch and a relay-fed stored response present, so
// the conversion cannot tell the transports apart.
func searchResults(ctx context.Context, md sdk.MetadataSource, query, kind string, body []byte, status int32, headers map[string]string) ([]map[string]any, error) {
	res, err := md.SearchResults(ctx, &metadatav1.SearchResultsRequest{
		Query: query, Kind: kind,
		Fetched: &metadatav1.FetchedResponse{Body: body, HttpStatus: status, Headers: headers, Fetched: true},
	})
	if err != nil {
		return nil, searchSentinel(err)
	}
	candidates := make([]map[string]any, 0, len(res.GetCandidates()))
	for _, c := range res.GetCandidates() {
		candidates = append(candidates, candidateMap(c))
	}
	return candidates, nil
}

// searchOverRelay is the identify search's relay leg (ruled OQ-6, D8): enqueue
// the plan as ONE purpose=search job (no ledger row — a search has no (row,
// plugin) pair to cool, D5) and hold the request here, polling until a
// terminal answer or the budget spends out. A done job feeds its stored
// response to the same searchResults call the direct fetch makes and is
// consumed (D4's read-that-fed); a failed job, an expired claim, or the spent
// budget answers byte-for-byte the error the endpoint answers with retry
// disabled. A transient store read error burns a tick and keeps polling; a
// cancelled context aborts the wait through the poll sleep.
func (q *Queue) searchOverRelay(ctx context.Context, md sdk.MetadataSource, pluginID, query, kind string, plan []relay.PlanSpec, fetchErr error) ([]map[string]any, error) {
	giveUp := func() ([]map[string]any, error) {
		return nil, fmt.Errorf("enrich: search fetch: %w", fetchErr)
	}
	if err := q.deps.Relay.Enqueue(ctx, plan, relayPurposeSearch, "", 0, pluginID, fetchClassNetwork, fetchErr.Error()); err != nil {
		return giveUp() // the relay store is broken: today's immediate answer
	}
	want, err := json.Marshal(plan)
	if err != nil { // PlanSpec never fails to marshal — guarded like Consult
		return giveUp()
	}
	deadline := now().Add(relaySearchBudget)
	for {
		job, found, err := newestSearchJob(ctx, q.deps.Relay, pluginID, want)
		if err == nil && found {
			switch {
			case job.state == relayStateDone:
				_ = q.deps.Relay.Store.MarkRelayConsumed(ctx, job.id) // best-effort: the read that fed SearchResults
				return searchResults(ctx, md, query, kind, job.result.Body, int32(job.result.HTTPStatus), job.result.Headers)
			case job.state == relayStateFailed:
				return giveUp()
			case job.state == relayStateClaimed && !job.leaseUntil.IsZero() && job.leaseUntil.Before(now()):
				return giveUp() // the claimant abandoned the job — the lazy expiry, read at the poll (D3)
			}
		}
		if !now().Before(deadline) {
			return giveUp()
		}
		if err := sleepContext(ctx, relaySearchPollInterval); err != nil {
			return giveUp() // the operator closed the picker: the wait aborts cleanly
		}
	}
}

// searchRelayJob is one poll tick's snapshot of the watched job row.
type searchRelayJob struct {
	id         int64
	state      string
	leaseUntil time.Time
	result     relay.RelayResult
}

// newestSearchJob is one poll tick's read: the newest purpose=search job for
// the plugin whose stored plan byte-equals the current plan — Consult's
// keying exactly (Enqueue returns no id, so the poll keys the row via the S10
// seam). An identical twin search converges on the same row, the stale twin
// staying unconsumed (Consult's safe degradation). found=false is just "no
// row yet".
func newestSearchJob(ctx context.Context, r *Relay, pluginID string, wantPlan []byte) (searchRelayJob, bool, error) {
	var (
		job    searchRelayJob
		lease  sql.NullString
		result []byte
	)
	err := r.Store.DB().QueryRowContext(ctx, `
SELECT id, state, lease_until, result FROM relay_jobs
WHERE purpose = ? AND plugin_id = ? AND plan = ?
ORDER BY id DESC LIMIT 1`, relayPurposeSearch, pluginID, string(wantPlan),
	).Scan(&job.id, &job.state, &lease, &result)
	if errors.Is(err, sql.ErrNoRows) {
		return searchRelayJob{}, false, nil
	}
	if err != nil {
		return searchRelayJob{}, false, fmt.Errorf("enrich: search relay poll %s: %w", pluginID, err)
	}
	if lease.Valid {
		if t, perr := time.Parse(time.RFC3339Nano, lease.String); perr == nil {
			job.leaseUntil = t // an unparseable stamp reads as no lease: the budget backstops
		}
	}
	if len(result) > 0 {
		if err := json.Unmarshal(result, &job.result); err != nil {
			return searchRelayJob{}, false, fmt.Errorf("enrich: search relay poll %s (result): %w", pluginID, err)
		}
	}
	return job, true, nil
}

// searchSentinel re-wraps an SDK error so the unsupported-search sentinel stays
// errors.Is-detectable above the api layer: in-process it already is; across
// the gRPC seam a plugin's plain error arrives as a status error carrying the
// sentinel text, and the seam's message round-trip is the detection.
func searchSentinel(err error) error {
	if err != nil && errors.Is(err, sdk.ErrSearchUnsupported) {
		return err
	}
	if err != nil && err.Error() == sdk.ErrSearchUnsupported.Error() {
		return fmt.Errorf("%w", sdk.ErrSearchUnsupported)
	}
	return fmt.Errorf("enrich: search: %w", err)
}

// candidateMap flattens one SearchCandidate into the convention-field map the
// api serves verbatim: the required trio always present, the optionals present
// only when the source set them (proto3 field presence — an absent field is
// never an empty string or zero).
func candidateMap(c *metadatav1.SearchCandidate) map[string]any {
	m := map[string]any{
		"external_id": c.GetExternalId(),
		"title":       c.GetTitle(),
		"kind":        c.GetKind(),
	}
	if c.RussianTitle != nil {
		m["russian_title"] = *c.RussianTitle
	}
	if c.Year != nil {
		m["year"] = *c.Year
	}
	if c.Episodes != nil {
		m["episodes"] = *c.Episodes
	}
	if c.Poster != nil {
		m["poster"] = *c.Poster
	}
	return m
}

// IdentifySeries re-anchors ONE series row's identity to the operator's
// picked candidate (identify-match-override): under the row's own
// non-blocking lease write identifiers.<pluginID>_id = externalID (OVERWRITE,
// no tombstone — enrichment D-4's precedent), persist, release, then run the
// explicit ReenrichSource strip for exactly this row (purge sans identifiers,
// flip pending, notify — the next pass fetches BY the picked id). Unknown
// plugin/series and an UNCONFIGURED source (D3) error before anything is
// written; a lease-held row reports (queued=false, deferred=1) with the
// document byte-identical. This is the series specialization of IdentifyItem
// — the shared anchor law is identifyAnchor's.
func (q *Queue) IdentifySeries(ctx context.Context, seriesID, pluginID, externalID string) (queued bool, stripped, deferred int, err error) {
	if externalID == "" {
		return false, 0, 0, errEmptyExternalID
	}
	if q.resolve != nil { // an unknown source errors before the write (the manager's accessor)
		if _, err = q.resolve(pluginID, metadataCapabilityID); err != nil {
			return false, 0, 0, err
		}
	}
	if !q.sourceConfigured(pluginID) { // D3: never write-then-dormant
		return false, 0, 0, sourcestate.ErrUnconfiguredSource
	}
	if !q.leases.acquire(seriesID, identifyOwner, q.cfg.LeaseTTL) {
		return false, 0, 1, nil // a worker owns the row: nothing written, retry later
	}
	sr, err := q.deps.Store.GetSeries(ctx, seriesID, access.System())
	if err != nil {
		q.leases.release(seriesID)
		return false, 0, 0, fmt.Errorf("enrich: identify: load series: %w", err)
	}
	docBytes, merr := identifyAnchor(decodeDoc(sr.Document), pluginID, externalID)
	if merr != nil { // keep the prior document on the impossible error
		q.leases.release(seriesID)
		return false, 0, 0, fmt.Errorf("enrich: identify: encode: %w", merr)
	}
	sr.Document = docBytes
	q.storeWrite(func() error { return q.deps.Store.PutSeries(ctx, sr) })
	q.leases.release(seriesID)

	stripped, deferred, err = q.ReenrichSource(ctx, sr.LibraryID, pluginID, seriesID)
	return true, stripped, deferred, err
}

// identifyAnchor writes the picked anchor into a document's identifiers — the
// anchor law BOTH identify actions share (tmdb-enrichment D5/D-4):
// identifiers.<pluginID>_id is OVERWRITTEN, numerically when the pick parses
// as an integer (the plugins' Match reads ids via intField), verbatim
// otherwise. Returns the marshaled document (a map never fails; callers keep
// the prior document on the impossible error).
func identifyAnchor(doc map[string]any, pluginID, externalID string) (json.RawMessage, error) {
	ids, _ := doc["identifiers"].(map[string]any)
	if ids == nil {
		ids = map[string]any{}
	}
	if n, perr := strconv.ParseInt(externalID, 10, 64); perr == nil {
		ids[pluginID+"_id"] = n
	} else {
		ids[pluginID+"_id"] = externalID
	}
	doc["identifiers"] = ids
	return json.Marshal(doc)
}

// IdentifyItem is the series identify law generalized over ANY queue row
// (tmdb-enrichment D5 — films are items in tv libraries): the same
// pre-action ordering, row lease, anchor write, and explicit ReenrichSource
// strip as IdentifySeries (see there), with loadRow — the item/series-agnostic
// loader, so an id naming a series row re-anchors it too — doing the read and
// the row's own persist sink landing the write. A gone row surfaces
// sql.ErrNoRows (%w-preserved — the api maps 404).
func (q *Queue) IdentifyItem(ctx context.Context, itemID, pluginID, externalID string) (queued bool, stripped, deferred int, err error) {
	if externalID == "" {
		return false, 0, 0, errEmptyExternalID
	}
	if q.resolve != nil { // an unknown source errors before the write (the manager's accessor)
		if _, err = q.resolve(pluginID, metadataCapabilityID); err != nil {
			return false, 0, 0, err
		}
	}
	if !q.sourceConfigured(pluginID) { // D3: never write-then-dormant
		return false, 0, 0, sourcestate.ErrUnconfiguredSource
	}
	if !q.leases.acquire(itemID, identifyOwner, q.cfg.LeaseTTL) {
		return false, 0, 1, nil // a worker owns the row: nothing written, retry later
	}
	row, err := q.loadRow(ctx, itemID)
	if err != nil {
		q.leases.release(itemID)
		// a gone row surfaces the loader's sql.ErrNoRows, %w-preserved for the
		// api's 404; any other read failure carries it verbatim.
		return false, 0, 0, fmt.Errorf("enrich: identify: load row: %w", err)
	}
	docBytes, merr := identifyAnchor(decodeDoc(row.doc), pluginID, externalID)
	if merr != nil { // keep the prior document on the impossible error
		q.leases.release(itemID)
		return false, 0, 0, fmt.Errorf("enrich: identify: encode: %w", merr)
	}
	row.persist(ctx, row.status, docBytes)
	q.leases.release(itemID)

	stripped, deferred, err = q.ReenrichSource(ctx, row.libraryID, pluginID, row.id)
	return true, stripped, deferred, err
}
